import{_ as t,o as a,c as o,ag as n}from"./chunks/framework.B7PviQjB.js";const s="/docs/images/slides/themes-and-layouts-theme-panel.png",u=JSON.parse('{"title":"Change themes and layouts","description":"Apply and customize a deck theme, edit layout placeholders, and set slide backgrounds.","frontmatter":{"title":"Change themes and layouts","description":"Apply and customize a deck theme, edit layout placeholders, and set slide backgrounds.","type":"how-to"},"headers":[],"relativePath":"slides/themes-and-layouts.md","filePath":"slides/themes-and-layouts.md"}'),l={name:"slides/themes-and-layouts.md"};function i(r,e,d,h,c,g){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="change-themes-and-layouts" tabindex="-1">Change themes and layouts <a class="header-anchor" href="#change-themes-and-layouts" aria-label="Permalink to &quot;Change themes and layouts&quot;">​</a></h1><p>Give a deck one consistent look with a theme, arrange slides with layouts, and set the background of one slide or all of them.</p><p>A theme sets the deck&#39;s colors, heading and body fonts, and default background. A layout sets which placeholders a slide has and where they sit. A new deck uses the <strong>Simple Light</strong> theme. The app&#39;s dark mode doesn&#39;t change the deck.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need edit access. A share-link viewer can&#39;t change the theme.</li><li>A share link, even with the editor role, has no <strong>Background</strong> button.</li><li>On a phone, the Theme and Background panels open from the <strong>More slide options</strong> (⋮) menu. See <a href="#on-a-phone">On a phone</a>.</li></ul></div><h2 id="apply-a-theme" tabindex="-1">Apply a theme <a class="header-anchor" href="#apply-a-theme" aria-label="Permalink to &quot;Apply a theme&quot;">​</a></h2><ol><li>Click <strong>Theme</strong> at the right end of the toolbar. The <strong>Theme</strong> panel opens.</li><li>On the <strong>Themes</strong> tab, click a theme.</li></ol><p>The whole deck changes at once, and your content stays in place. Each card shows the theme&#39;s name, an <code>aA</code> type sample on its background, and its six accent colors.</p><p>Objects colored with theme colors change with the theme. Objects you gave a custom color keep it.</p><p><img src="'+s+'" alt="Theme panel on the Themes tab with theme cards and Streamline selected"></p><h2 id="customize-the-theme" tabindex="-1">Customize the theme <a class="header-anchor" href="#customize-the-theme" aria-label="Permalink to &quot;Customize the theme&quot;">​</a></h2><ol><li>Click <strong>Theme</strong> and open the <strong>Customize</strong> tab.</li><li>Change any of these: <ul><li><strong>Colors</strong>: the 12 theme colors, such as Text, Background, Accent 1 to 6, Link, and Visited link.</li><li><strong>Fonts</strong>: the <strong>Headings</strong> and <strong>Body</strong> fonts.</li><li><strong>Background</strong>: the color used by every slide that has no background of its own. Click <strong>Match theme</strong> to undo a change here.</li></ul></li></ol><p>Each change applies to the whole deck right away and is one undo step. Once you change a built-in theme, it appears under <strong>In this presentation</strong> on the <strong>Themes</strong> tab. To discard your changes, click <strong>Reset to original</strong> on the <strong>Customize</strong> tab.</p><h2 id="edit-layout-placeholders" tabindex="-1">Edit layout placeholders <a class="header-anchor" href="#edit-layout-placeholders" aria-label="Permalink to &quot;Edit layout placeholders&quot;">​</a></h2><ol><li>Click <strong>Theme</strong> and open the <strong>Customize</strong> tab.</li><li>Under <strong>Layouts</strong>, click <strong>Edit layout positions</strong>. A banner appears above the slide.</li><li>The slide strip lists the layouts, starting on the current slide&#39;s layout. Click a layout to edit it.</li><li>Drag the placeholders to new positions.</li><li>Click <strong>Done</strong> in the banner.</li></ol><p>The new positions apply to every slide that uses that layout. Layout editing isn&#39;t available on a phone.</p><h2 id="change-a-slide-s-layout" tabindex="-1">Change a slide&#39;s layout <a class="header-anchor" href="#change-a-slide-s-layout" aria-label="Permalink to &quot;Change a slide&#39;s layout&quot;">​</a></h2><ol><li>Right-click the slide&#39;s thumbnail in the slide strip, or an empty part of the slide.</li><li>Select <strong>Change layout…</strong> and pick a layout.</li></ol><p>The title stays a title and body text stays in the body. Text you type in a placeholder uses the theme&#39;s heading or body font, so it matches the deck without extra formatting. To pick the layout of a new slide instead, use the arrow next to <strong>Add slide</strong>. See <a href="/docs/slides/add-content.html#add-a-slide">Add a slide</a>.</p><h2 id="change-one-slide-s-background" tabindex="-1">Change one slide&#39;s background <a class="header-anchor" href="#change-one-slide-s-background" aria-label="Permalink to &quot;Change one slide&#39;s background&quot;">​</a></h2><ol><li>Open the slide and click <strong>Background</strong> at the right end of the toolbar (tooltip <strong>Slide background</strong>).</li><li>Under <strong>Color</strong>, use the <strong>Solid</strong> tab for one color, or the <strong>Gradient</strong> tab for a linear gradient.</li><li>Or, under <strong>Image</strong>, click <strong>Choose image…</strong> and pick a file. Use <strong>Opacity</strong> to fade it, <strong>Replace image…</strong> to swap it, and <strong>Remove image</strong> to take it away.</li></ol><p>A slide&#39;s own background is a color or an image, not both. Setting one clears the other. The panel follows you to whichever slide you open.</p><p>To go back to the theme&#39;s background, click <strong>Reset to theme</strong>.</p><h2 id="apply-a-background-to-all-slides" tabindex="-1">Apply a background to all slides <a class="header-anchor" href="#apply-a-background-to-all-slides" aria-label="Permalink to &quot;Apply a background to all slides&quot;">​</a></h2><ol><li>Set the background you want on one slide.</li><li>Click <strong>Apply to all slides</strong> at the bottom of the <strong>Background</strong> panel.</li></ol><p>The background becomes the deck&#39;s default. Slides that have their own background keep it.</p><h2 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h2><ol><li>Tap <strong>More slide options</strong> (⋮) in the toolbar.</li><li>Under <strong>Design</strong>, select <strong>Theme…</strong> or <strong>Slide background…</strong>. The panel opens as a sheet.</li></ol><h2 id="built-in-themes" tabindex="-1">Built-in themes <a class="header-anchor" href="#built-in-themes" aria-label="Permalink to &quot;Built-in themes&quot;">​</a></h2><p>There are 23 built-in themes. They appear in the panel in this order:</p><p>Simple Light, Simple Dark, Streamline, Swiss, Paradigm, Material, Shift, Momentum, Focus, Luxe, Modern Writer, Coral, Spearmint, Pop, Tropic, Marina, Geometric, Plum, Slate, Forest, Spotlight, Beach Day, and Wafflebase.</p><h2 id="built-in-layouts" tabindex="-1">Built-in layouts <a class="header-anchor" href="#built-in-layouts" aria-label="Permalink to &quot;Built-in layouts&quot;">​</a></h2><p>Layouts appear in the picker in this order.</p><table tabindex="0"><thead><tr><th>Layout</th><th>Use it for</th></tr></thead><tbody><tr><td>Blank</td><td>An empty slide with no placeholders</td></tr><tr><td>Title slide</td><td>The opening slide, with a title and subtitle</td></tr><tr><td>Section header</td><td>A divider between groups of slides</td></tr><tr><td>Title and body</td><td>A title above one text area</td></tr><tr><td>Title and two columns</td><td>A title above two side-by-side areas</td></tr><tr><td>Title only</td><td>A title with the rest of the slide empty</td></tr><tr><td>One column text</td><td>A full-width text area for longer prose</td></tr><tr><td>Main point</td><td>One large centered statement</td></tr><tr><td>Section title and description</td><td>A section title with a paragraph</td></tr><tr><td>Caption</td><td>A large image area with a caption below</td></tr><tr><td>Big number</td><td>One large number as the focus</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/slides/add-content.html">Add content</a> to fill placeholders with text and images.</li><li><a href="/docs/slides/style-and-arrange.html">Style and arrange</a> to color objects with theme colors.</li><li><a href="/docs/files/import-export.html">Import and export</a> to bring in a PowerPoint deck with its own theme.</li></ul>',35)])])}const m=t(l,[["render",i]]);export{u as __pageData,m as default};
